#requires -version 5.1
[CmdletBinding()]
param(
    [string]$XperfExe = '',
    [string]$OutputDir = $PSScriptRoot,
    [int]$IdleWaitSeconds = 120,
    [int]$TraceSeconds = 20,
    [switch]$SkipIdleWait
)

$ErrorActionPreference = 'Stop'
$Invariant = [System.Globalization.CultureInfo]::InvariantCulture

function Format-Num([double]$Value, [string]$Pattern) {
    return $Value.ToString($Pattern, $Invariant)
}

function Resolve-XperfPath([string]$Explicit) {
    if ($Explicit) {
        if (Test-Path -LiteralPath $Explicit) {
            return (Resolve-Path -LiteralPath $Explicit).Path
        }
        throw "[!] Error: xperf.exe not found at '$Explicit'!"
    }
    $candidates = @(
        (Join-Path $PSScriptRoot 'xperf\xperf.exe'),
        (Join-Path $OutputDir 'xperf\xperf.exe'),
        'C:\Program Files\Hypertune\xperf\xperf.exe'
    )
    foreach ($candidate in $candidates) {
        if (Test-Path -LiteralPath $candidate) {
            return (Resolve-Path -LiteralPath $candidate).Path
        }
    }
    throw '[!] Error: xperf.exe not found in xperf/ folder!'
}

function ConvertTo-ArgumentString([string[]]$Items) {
    $quoted = foreach ($item in $Items) {
        if ($item -match '[\s"]') {
            '"' + ($item -replace '"', '\"') + '"'
        } else {
            $item
        }
    }
    return ($quoted -join ' ')
}

function Invoke-Xperf {
    param(
        [string]$Stage,
        [string[]]$Arguments,
        [switch]$AllowFailure
    )

    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $script:XperfPath
    $psi.Arguments = ConvertTo-ArgumentString $Arguments
    $psi.WorkingDirectory = $script:WorkDir
    $psi.UseShellExecute = $false
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $psi.CreateNoWindow = $true

    $proc = [System.Diagnostics.Process]::Start($psi)
    $stdout = $proc.StandardOutput.ReadToEnd()
    $stderr = $proc.StandardError.ReadToEnd()
    $proc.WaitForExit()
    $exitCode = $proc.ExitCode

    $diagnostics = (($stdout + $stderr).Trim())
    if ($exitCode -ne 0 -and -not $AllowFailure) {
        if (-not $diagnostics) { $diagnostics = 'No diagnostic output' }
        throw "$Stage failed with exit code $exitCode`: $diagnostics"
    }
    return $diagnostics
}

function Read-ReportLines([string]$Path) {
    # Matches Python's open(path, encoding="utf-8", errors="ignore") closely:
    # invalid byte sequences are replaced instead of aborting the read.
    $encoding = New-Object System.Text.UTF8Encoding($false, $false)
    return [System.IO.File]::ReadAllLines($Path, $encoding)
}

function Save-Report([string]$Path, [string[]]$Lines) {
    $encoding = New-Object System.Text.UTF8Encoding($false)
    $text = ($Lines -join "`r`n") + "`r`n"
    [System.IO.File]::WriteAllText($Path, $text, $encoding)
}

$script:XperfPath = Resolve-XperfPath $XperfExe
$script:WorkDir = $OutputDir
if (-not (Test-Path -LiteralPath $script:WorkDir)) {
    New-Item -ItemType Directory -Path $script:WorkDir -Force | Out-Null
}
$script:WorkDir = (Resolve-Path -LiteralPath $script:WorkDir).Path

$testId = $PID
$etlFile = Join-Path $script:WorkDir "dpc-isr-$testId.etl"
$txtFile = Join-Path $script:WorkDir "dpc-isr-$testId.txt"
$sumFile = Join-Path $script:WorkDir "dpc-isr-sum-$testId.txt"
$flagFile = Join-Path $script:WorkDir 'xperf_ready.flag'

$traceStarted = $false

try {
    Write-Host '[~] Starting Deferred Xperf Pipeline (0% GUI Latency Mode)'

    if (-not $SkipIdleWait) {
        Write-Host "[~] Waiting $IdleWaitSeconds seconds for system idle stabilization..."
        Start-Sleep -Seconds $IdleWaitSeconds
    }

    Invoke-Xperf -Stage 'Stopping an existing Xperf session' -Arguments @('-stop') -AllowFailure | Out-Null
    Invoke-Xperf -Stage 'Stopping the NT Kernel Logger' -Arguments @('-stop', 'NT Kernel Logger') -AllowFailure | Out-Null

    Write-Host "[~] Starting ${TraceSeconds}s Xperf DPC/ISR Trace..."
    $traceStarted = $true
    Invoke-Xperf -Stage 'Starting the Xperf trace' -Arguments @('-on', 'PROC_THREAD+LOADER+DPC+INTERRUPT') | Out-Null

    Start-Sleep -Seconds $TraceSeconds

    Write-Host '[~] Flushing trace buffer to ETL...'
    Invoke-Xperf -Stage 'Saving the Xperf trace' -Arguments @('-d', $etlFile) | Out-Null

    if (-not (Test-Path -LiteralPath $etlFile)) {
        throw 'Xperf reported success but did not create the ETL trace file.'
    }

    Write-Host '[~] Analyzing DPC/ISR modules...'
    Invoke-Xperf -Stage 'Analyzing the Xperf trace' -Arguments @('-i', $etlFile, '-o', $txtFile, '-a', 'dpcisr') | Out-Null

    if (-not (Test-Path -LiteralPath $txtFile)) {
        throw 'Xperf analysis reported success but did not create its text report.'
    }

    $lines = Read-ReportLines $txtFile

    $dictDpc = @{}
    $dictIsr = @{}
    [double]$countDpc = 0.0
    [double]$countIsr = 0.0
    [double]$totalDpc = 0.0
    [double]$totalIsr = 0.0
    [double]$intervalTime = 0.0
    $isDpc = $false
    $isIsr = $false

    foreach ($rawLine in $lines) {
        $lineStr = $rawLine.Trim()

        if ($lineStr -like '*DPC Info*') {
            $isDpc = $true
            $isIsr = $false
            continue
        }
        if ($lineStr -like '*Interrupt Info*') {
            $isDpc = $false
            $isIsr = $true
            continue
        }

        if ($lineStr -like '*CPU Usage from*') {
            $match = [regex]::Match($lineStr, 'from\s+([0-9.]+)\s*us\s+to\s+([0-9.]+)\s*us')
            if ($match.Success) {
                try {
                    $startUs = [double]::Parse($match.Groups[1].Value, $Invariant)
                    $endUs = [double]::Parse($match.Groups[2].Value, $Invariant)
                    $intervalTime = $endUs - $startUs
                } catch {
                    $intervalTime = 0.0
                }
            }
            continue
        }

        if ($lineStr -like '*Total = *' -and $lineStr -like '*for module*') {
            $match = [regex]::Match($lineStr, 'Total\s*=\s*([0-9.]+)\s+for module\s+(.+)$')
            if ($match.Success) {
                try {
                    $value = [double]::Parse($match.Groups[1].Value, $Invariant)
                    $moduleName = $match.Groups[2].Value.Trim()
                    if ($moduleName) {
                        if ($isDpc) {
                            $dictDpc[$moduleName] = $value
                            $countDpc += $value
                        } elseif ($isIsr) {
                            $dictIsr[$moduleName] = $value
                            $countIsr += $value
                        }
                    }
                } catch {
                    # The original parser tolerates bad numeric tokens here.
                }
            }
            continue
        }

        # Per-CPU usage row: "<usec> <pct>, <usec> <pct>, ..., <module>"
        if (($isDpc -or $isIsr) -and $lineStr.Contains(',')) {
            $parts = $lineStr.Split(',')
            if ($parts.Count -ge 2) {
                $moduleName = $parts[$parts.Count - 1].Trim()
                if ($moduleName -and $moduleName -ne 'Module' -and $moduleName -notmatch '\s') {
                    [double]$rowTotal = 0.0
                    $parsedAny = $false
                    for ($i = 0; $i -lt ($parts.Count - 1); $i++) {
                        $tokens = $parts[$i].Trim().Split([char[]]@(' ', "`t"), [System.StringSplitOptions]::RemoveEmptyEntries)
                        if ($tokens.Count -ge 1) {
                            [double]$usec = 0.0
                            if ([double]::TryParse($tokens[0], [System.Globalization.NumberStyles]::Float, $Invariant, [ref]$usec)) {
                                $rowTotal += $usec
                                $parsedAny = $true
                            }
                        }
                    }
                    if ($parsedAny) {
                        if ($isDpc) {
                            $totalDpc += $rowTotal
                        } else {
                            $totalIsr += $rowTotal
                        }
                    }
                }
            }
        }
    }

    $outLines = New-Object System.Collections.Generic.List[string]

    $outLines.Add('----- Total DPC -----')
    foreach ($entry in ($dictDpc.GetEnumerator() | Sort-Object -Property Value -Descending)) {
        $outLines.Add("$($entry.Key) -> $(Format-Num $entry.Value '0.0')")
    }

    $outLines.Add('')
    $outLines.Add('----- Total ISR -----')
    foreach ($entry in ($dictIsr.GetEnumerator() | Sort-Object -Property Value -Descending)) {
        $outLines.Add("$($entry.Key) -> $(Format-Num $entry.Value '0.0')")
    }

    if ($intervalTime -le 0) {
        $outLines.Add('')
        $outLines.Add('[!] Xperf output did not contain a usable CPU interval; weighted values could not be calculated.')
        Save-Report -Path $sumFile -Lines $outLines.ToArray()
        [System.IO.File]::WriteAllText($flagFile, $sumFile, (New-Object System.Text.UTF8Encoding($false)))
        Write-Host "[!] Xperf output did not contain a usable CPU interval; weighted values could not be calculated."
        exit 0
    }

    $dpcWeighted = if ($countDpc -gt 0) { $totalDpc / $countDpc } else { 0.0 }
    $isrWeighted = if ($countIsr -gt 0) { $totalIsr / $countIsr } else { 0.0 }
    $totalCount = $countDpc + $countIsr
    $totalWeighted = if ($totalCount -gt 0) { ($totalDpc + $totalIsr) / $totalCount } else { 0.0 }
    $dpcImpact = $totalDpc / $intervalTime * 100.0
    $isrImpact = $totalIsr / $intervalTime * 100.0
    $totalImpact = $dpcImpact + $isrImpact

    $outLines.Add('')
    $outLines.Add('----- DPC/ISR Weighted -----')
    $outLines.Add("DPC Weighted Latency (us): $(Format-Num $dpcWeighted '0.000')")
    $outLines.Add("ISR Weighted Latency (us): $(Format-Num $isrWeighted '0.000')")
    $outLines.Add("Total Weighted Latency (us): $(Format-Num $totalWeighted '0.000')")

    $outLines.Add('')
    $outLines.Add('----- DPC/ISR Effective Impact (%) -----')
    $outLines.Add("DPC Impact (%): $(Format-Num $dpcImpact '0.000')")
    $outLines.Add("ISR Impact (%): $(Format-Num $isrImpact '0.000')")
    $outLines.Add("Total Impact (%): $(Format-Num $totalImpact '0.000')")

    Save-Report -Path $sumFile -Lines $outLines.ToArray()
    [System.IO.File]::WriteAllText($flagFile, $sumFile, (New-Object System.Text.UTF8Encoding($false)))

    Write-Host "Report written: $sumFile"
} catch {
    Write-Host "[!] Error: $($_.Exception.Message)"
    if ($traceStarted) {
        try {
            Invoke-Xperf -Stage 'Stopping the failed Xperf trace' -Arguments @('-stop') -AllowFailure | Out-Null
        } catch {
            # Best-effort cleanup only.
        }
    }
    Write-Host 'Xperf trace failed.'
    exit 1
}

