$ErrorActionPreference = 'Stop'
$app = 'C:\Program Files\Hypertune\Hypertune.exe'
$dir = 'C:\Program Files\Hypertune'
$tmp = 'C:\Users\Administrator\AppData\Local\Temp\xpauto'
New-Item -ItemType Directory -Force -Path $tmp | Out-Null

Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
Add-Type @"
using System;
using System.Runtime.InteropServices;
public class NativeW {
    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
    [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);
    [DllImport("user32.dll")] public static extern bool SetCursorPos(int X, int Y);
    [DllImport("user32.dll")] public static extern void mouse_event(uint dwFlags, uint dx, uint dy, uint dwData, UIntPtr dwExtraInfo);
    public struct RECT { public int Left; public int Top; public int Right; public int Bottom; }
}
"@

function Save-Shot([string]$name) {
    try {
        $bounds = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
        $bmp = New-Object System.Drawing.Bitmap $bounds.Width, $bounds.Height
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        $g.CopyFromScreen($bounds.Location, [System.Drawing.Point]::Empty, $bounds.Size)
        $bmp.Save((Join-Path $tmp $name), [System.Drawing.Imaging.ImageFormat]::Png)
        $g.Dispose(); $bmp.Dispose()
    } catch { }
}

function Find-ElementByName([string]$name, [int]$timeoutSeconds = 8) {
    $cond = New-Object System.Windows.Automation.PropertyCondition(
        [System.Windows.Automation.AutomationElement]::NameProperty, $name)
    $deadline = (Get-Date).AddSeconds($timeoutSeconds)
    do {
        $el = [System.Windows.Automation.AutomationElement]::RootElement.FindFirst(
            [System.Windows.Automation.TreeScope]::Descendants, $cond)
        if ($el) { return $el }
        Start-Sleep -Milliseconds 400
    } while ((Get-Date) -lt $deadline)
    return $null
}

function Invoke-Element($el) {
    $pattern = $el.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern)
    $pattern.Invoke()
}

function Click-WindowPoint([IntPtr]$hwnd, [double]$fx, [double]$fy) {
    $rect = New-Object NativeW+RECT
    [void][NativeW]::GetWindowRect($hwnd, [ref]$rect)
    $x = [int]($rect.Left + ($rect.Right - $rect.Left) * $fx)
    $y = [int]($rect.Top + ($rect.Bottom - $rect.Top) * $fy)
    [void][NativeW]::SetForegroundWindow($hwnd)
    Start-Sleep -Milliseconds 300
    [void][NativeW]::SetCursorPos($x, $y)
    Start-Sleep -Milliseconds 150
    [NativeW]::mouse_event(0x0002, 0, 0, 0, [UIntPtr]::Zero)
