function ConvertTo-ArgumentString([string[]]$Items) {
    $quoted = foreach ($item in $Items) {
        if ($item -match '[\s"]') {
            '"' + ($item -replace '"', '\"') + '"'
        } else {
            $item
        }
    }
    return ($quoted -join ' ')
}

function Invoke-Xperf {
    param(
