    $stderr = $proc.StandardError.ReadToEnd()
    $proc.WaitForExit()
    $exitCode = $proc.ExitCode

    $diagnostics = (($stdout + $stderr).Trim())
    if ($exitCode -ne 0 -and -not $AllowFailure) {
        if (-not $diagnostics) { $diagnostics = 'No diagnostic output' }
        throw "$Stage failed with exit code $exitCode`: $diagnostics"
    }
    return $diagnostics
}

function Read-ReportLines([string]$Path) {
